/**
 * One icon from its SVG path. Material Symbols draw in a 960 box whose top edge sits at
 * y = -960, so the path is moved down into view; a few older ones use the plain 24 grid.
 */
private fun symbol(name: String, path: String, viewport: Float = 960f): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, viewport, viewport).run {
        addGroup(translationY = if (viewport == 960f) 960f else 0f)
        addPath(addPathNodes(path), fill = SolidColor(Color.Black))
        clearGroup()
        build()
    }
